CREATE TABLE published_orders(id integer PRIMARY KEY, total integer);
CREATE TABLE published_invoices(id integer PRIMARY KEY, total integer);
INSERT INTO published_orders VALUES(1,10);
INSERT INTO published_invoices VALUES(1,10);
BEGIN;
UPDATE published_orders SET total=20 WHERE id=1;
UPDATE published_invoices SET total=20 WHERE id=1;
ALTER TABLE published_orders RENAME COLUMN total TO amount;
COMMENT ON TABLE published_orders IS 'confirmed order';
CREATE INDEX published_order_amount ON published_orders(amount);
COMMIT;
SELECT o.amount,i.total FROM published_orders o JOIN published_invoices i ON o.id=i.id;
SELECT obj_description('published_orders'::regclass);
BEGIN;
UPDATE published_orders SET amount=30 WHERE id=1;
UPDATE published_invoices SET total=30 WHERE id=1;
ALTER TABLE published_orders RENAME COLUMN amount TO total;
COMMENT ON TABLE published_orders IS 'discarded order';
DROP INDEX published_order_amount;
ROLLBACK;
SELECT o.amount,i.total FROM published_orders o JOIN published_invoices i ON o.id=i.id;
SELECT obj_description('published_orders'::regclass);
SELECT count(*) FROM pg_indexes WHERE indexname='published_order_amount';
